package org.apache.commons.math3.optimization.linear;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MaxCountExceededException;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.util.Precision;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for SimplexSolver.doIteration.
 * Since doIteration is protected, we use a Testable subclass to expose it.
 */
public class SimplexSolver_doIteration_TriageGen1Test {

    private TestableSimplexSolver solver;
    private SimplexTableau mockTableau;

    // Testable subclass to access protected method and mock its internal dependencies
    private static class TestableSimplexSolver extends SimplexSolver {
        private Integer forcedPivotCol;
        private Integer forcedPivotRow;

        public TestableSimplexSolver() {
            super();
        }

        public void setForcedPivot(Integer col, Integer row) {
            this.forcedPivotCol = col;
            this.forcedPivotRow = row;
        }

        @Override
        protected Integer getPivotColumn(SimplexTableau tableau) {
            return forcedPivotCol;
        }

        @Override
        protected Integer getPivotRow(SimplexTableau tableau, Integer pivotCol) {
            return forcedPivotRow;
        }

        @Override
        protected void incrementIterationsCounter() {
            // No-op for testing
        }

        @Override
        public PointValuePair doOptimize() throws MaxCountExceededException, UnboundedSolutionException, org.apache.commons.math3.optim.NonNegativeConvergenceException {
            return null;
        }
    }

    @Before
    public void setUp() {
        solver = new TestableSimplexSolver();
        mockTableau = mock(SimplexTableau.class);
    }

    @Test
    public void testDoIteration_UnboundedSolution() throws MaxCountExceededException, UnboundedSolutionException {
        // Setup: pivotRow is null
        solver.setForcedPivot(1, null);

        try {
            solver.doIteration(mockTableau);
            org.junit.Assert.fail("Expected UnboundedSolutionException was not thrown");
        } catch (UnboundedSolutionException e) {
            // Success
        }
    }

    @Test
    public void testDoIteration_SuccessfulPivot() throws MaxCountExceededException, UnboundedSolutionException {
        // Setup: pivotCol = 1, pivotRow = 1, tableau height = 3
        int pivotCol = 1;
        int pivotRow = 1;
        double pivotVal = 2.0;

        solver.setForcedPivot(pivotCol, pivotRow);
        when(mockTableau.getEntry(pivotRow, pivotCol)).thenReturn(pivotVal);
        when(mockTableau.getHeight()).thenReturn(3);

        // Mock entries for other rows in the pivot column to test the loop
        // Row 0: multiplier 0.5
        // Row 2: multiplier 3.0
        when(mockTableau.getEntry(0, pivotCol)).thenReturn(0.5);
        when(mockTableau.getEntry(2, pivotCol)).thenReturn(3.0);

        solver.doIteration(mockTableau);

        // Verify pivot element division
        verify(mockTableau, times(1)).divideRow(pivotRow, pivotVal);

        // Verify row subtractions (loop)
        // i=0 (i != pivotRow)
        verify(mockTableau, times(1)).subtractRow(0, pivotRow, 0.5);
        // i=1 (i == pivotRow) -> should NOT call subtractRow
        verify(mockTableau, never()).subtractRow(eq(1), eq(pivotRow), anyDouble());
        // i=2 (i != pivotRow)
        verify(mockTableau, times(1)).subtractRow(2, pivotRow, 3.0);
    }

    @Test
    public void testDoIteration_SingleRowTableau() throws MaxCountExceededException, UnboundedSolutionException {
        // Setup: pivotCol = 0, pivotRow = 0, tableau height = 1
        int pivotCol = 0;
        int pivotRow = 0;
        double pivotVal = 5.0;

        solver.setForcedPivot(pivotCol, pivotRow);
        when(mockTableau.getEntry(pivotRow, pivotCol)).thenReturn(pivotVal);
        when(mockTableau.getHeight()).thenReturn(1);

        solver.doIteration(mockTableau);

        // Verify division
        verify(mockTableau, times(1)).divideRow(pivotRow, pivotVal);
        // Verify loop: i=0 is pivotRow, so no subtractRow should be called
        verify(mockTableau, never()).subtractRow(anyInt(), anyInt(), anyDouble());
    }
}
